//! Native abortable listeners preserve identity, dispatch snapshots and authority.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=main>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://listener.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var owner=new Document(),root=owner.createElement('Root'),leaf=owner.createElement('Leaf');owner.appendChild(root);root.appendChild(leaf);var c=new AbortController(),s=c.signal,calls=0,event=new Event('check',{bubbles:true});function callback(){calls++;}");(d,f,p)}
#[test]
fn event_listener_signal_actual_targets_remove_before_abort_event_and_skip_preaborted(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var targets=[leaf,root,owner,document,window,new EventTarget(),document.getElementById('main')],seen=0;for(var target of targets)target.addEventListener('check',callback,{signal:s});s.addEventListener('abort',function(e){if(!s.aborted||s.reason!==reason||!e.isTrusted)throw 'native abort state';for(var target of targets)target.dispatchEvent(event);seen++;});s.addEventListener('abort',function(){seen+=100;},{signal:s});var reason={};c.abort(reason);if(calls||seen!==1||s.reason!==reason)throw 'remove all attached listeners before abort callbacks';for(var target of targets){target.addEventListener('check',callback,{signal:s});target.dispatchEvent(event);}if(calls)throw 'already aborted signal admission';
"#);assert_eq!(p.state.listeners.len(),1);assert!(p.state.synthetic_dispatches.is_empty());}
#[test]
fn event_listener_signal_duplicate_capture_once_and_remove_readd_keep_actual_registration(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var second=new AbortController();leaf.addEventListener('check',callback,{signal:s});leaf.addEventListener('check',callback,{signal:second.signal,once:true,passive:true});second.abort();leaf.dispatchEvent(event);leaf.dispatchEvent(event);if(calls!==2)throw 'duplicate does not replace options or signal';c.abort();leaf.dispatchEvent(event);if(calls!==2)throw 'original registration signal removes';var old=new AbortController();leaf.addEventListener('check',callback,{signal:old.signal});leaf.removeEventListener('check',callback,{capture:false,signal:1});leaf.addEventListener('check',callback);old.abort();leaf.dispatchEvent(event);if(calls!==3)throw 'removed registration signal must not remove readded callback';leaf.removeEventListener('check',callback);var split=new AbortController();leaf.addEventListener('check',callback,{signal:split.signal,capture:true});leaf.addEventListener('check',callback,{capture:false,once:true});split.abort();leaf.dispatchEvent(event);leaf.dispatchEvent(event);if(calls!==4)throw 'capture identity and independent once';
"#);assert!(p.state.listeners.is_empty());}
#[test]
fn event_listener_signal_current_dispatch_skips_aborted_snapshots_and_nested_reentry(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var log='',listener={handleEvent:function(e){log+='X';}};root.addEventListener('check',function(){log+='C';c.abort();root.addEventListener('check',listener,{signal:s});leaf.dispatchEvent(new Event('nested'));},true);root.addEventListener('check',listener,{signal:s});leaf.addEventListener('check',listener,{signal:s});leaf.addEventListener('nested',function(){log+='N';});s.addEventListener('abort',function(){log+='A';leaf.dispatchEvent(new Event('check2'));});leaf.addEventListener('check2',function(){log+='R';});leaf.addEventListener('check',function(){log+='T';});leaf.dispatchEvent(event);if(log!=='CARNT'||s.aborted!==true)throw 'snapshot removals before current target and bubble';
"#);assert!(p.state.synthetic_dispatches.is_empty());assert!(p.state.created_events.iter().all(|e|!e.dispatching));}
#[test]
fn event_listener_signal_dictionary_brand_order_and_borrowed_method_authority(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var read='',options={get capture(){read+='c';return false;},get once(){read+='o';return true;},get passive(){read+='p';return false;},get signal(){read+='s';return s;}};leaf.addEventListener('check',callback,options);if(read!=='cops')throw 'dictionary order';var rejected=0;for(var value of [null,1,{},new EventTarget(),c,document])try{leaf.addEventListener('check',null,{signal:value});}catch(e){if(e.name==='TypeError')rejected++;else throw e;}if(rejected!==6)throw 'genuine signal dictionary brand';leaf.removeEventListener('check',callback);var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var ForeignAbort=frame.contentWindow.AbortController,foreignController=new ForeignAbort(),foreignSignal=foreignController.signal;var foreignAdd=frame.contentWindow.EventTarget.prototype.addEventListener,foreignRemove=frame.contentWindow.EventTarget.prototype.removeEventListener,boundAdd=foreignAdd.bind(leaf),boundRemove=foreignRemove.bind(leaf);foreignAdd.call(leaf,'check',callback);foreignRemove.call(leaf,'check',callback);leaf.addEventListener('check',callback);
"#);let count=p.state.listeners.len();p.set_location(&crate::navigation::address("https://other.test/source",&crate::navigation::Location::home()).unwrap());for source in ["foreignAdd.call(leaf,'new',callback)","boundAdd('new',callback)","foreignRemove.call(leaf,'check',callback)","boundRemove('check',callback)","foreignAdd.call(document.getElementById('main'),'new',callback)","EventTarget.prototype.addEventListener.call(leaf,'new',callback,{signal:foreignSignal})"]{p.begin_job();let error=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!(p.state.listeners.len(),count);}p.set_location(&crate::navigation::address("https://listener.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"foreignRemove.call(leaf,'check',callback);leaf.dispatchEvent(event);if(calls)throw 'saved method authority recovery';foreignAdd.call(leaf,'check',callback,{signal:s});leaf.dispatchEvent(event);if(calls!==1)throw 'borrowed listener fresh recovery';leaf.addEventListener('foreign',callback,{signal:foreignSignal});leaf.dispatchEvent(new Event('foreign'));foreignController.abort();leaf.dispatchEvent(new Event('foreign'));if(calls!==2)throw 'genuine child signal owner and abort cleanup';");}
#[test]
fn event_listener_signal_refusal_is_atomic_and_abort_admission_recovers(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();let before=(p.state.retained,p.state.listeners.len());let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())}assert!(p.runtime.execute("leaf.addEventListener('check',callback,{signal:s})",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.retained,p.state.listeners.len()),before);p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"leaf.addEventListener('check',callback,{signal:s});leaf.dispatchEvent(event);if(calls!==1)throw 'listener registration recovery';");let retained=p.state.retained;p.state.retained_limit=retained;p.begin_job();assert!(p.runtime.execute("c.abort(null)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!(p.state.retained,retained);assert_eq!(p.state.listeners.len(),1);assert!(p.state.synthetic_dispatches.is_empty());p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(s.aborted||s.reason!==undefined)throw 'failed abort committed';leaf.dispatchEvent(event);if(calls!==2)throw 'failed abort removed listener';c.abort('recovered');leaf.dispatchEvent(event);if(calls!==2||s.reason!=='recovered')throw 'fresh abort removes listener';");assert!(p.state.listeners.is_empty());}
}
